-- 001_migration_plan.sql
-- Rebuilt classification file for the alpha.mdm -> crims.mdm migration.
--
-- Decisions applied (2026-09-23):
--   G18 fund_hierarchy -> public.tenants FK: DROPPED; enforce via RLS/GUC.
--   G22 alpha.public fabric tables: use existing plural (business_objects etc.).
--   G20 base classification: never persisted on disk -> this file IS the
--       authoritative rebuild; supersedes classification_seed_additions.sql.
--   FABRIC_REF + FABRIC_RULE -> crims.mdm (no longer alpha.public):
--       reference/rule data is data-plane; keeps 130 cross-DB FKs same-home.
--       alpha.public fabric (catalog/semantic) remains in alpha.control_plane.
--   G15 subtype_registry_seed does not exist -> row removed (G15 phantom).
--   G16 issuer_master -> crims.mdm.issuer_master (crims has no edm schema).
--   G19 issuer pattern repeated for benchmark_master / curve_master /
--       fx_rate_master; mdm versions win (richer, 18 inbound FKs vs edm 3),
--       edm golden-copy twins are dropped.
--   G21 party/xref: reuse crims.mdm.xref with entity_type='party'.
--   COLLISION_party:       both 0 rows; alpha schema wins -> replace empty
--                          crims.mdm.party; port crims RLS; add party_cd.
--   COLLISION_rating_scale: alpha has 31 rows + rating->rating_scale FK;
--                          alpha schema wins.
--   LINEAGE_TBD 12 edm *_trace/*_lineage tables: reclassified DATA_LINEAGE
--                          -> crims.mdm (preserves 7 cross stay<->move FKs).
--   CROSS-DB FKs REMAINING after decisions: G18 + 2 (preference_versions,
--       portfolio_master edges into INFRA-side) -> drop + app-enforce.
--
-- Run against CRIMS. Idempotent (ON CONFLICT DO NOTHING).

-- migration schema (lives on crims master) ----------------------------
CREATE SCHEMA IF NOT EXISTS migration;

-- migration.plan: every classified table -------------------------------
CREATE TABLE IF NOT EXISTS migration.plan (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source_db       text NOT NULL,
  source_schema   text NOT NULL,
  source_table    text NOT NULL,
  target_db       text NOT NULL,
  target_schema   text,
  target_table    text,
  classification  text NOT NULL,
  domain          text NOT NULL,
  batch_order     int  NOT NULL,
  notes           text,
  UNIQUE (source_db, source_schema, source_table)
);

-- migration.progress: per-row copy status --------------------------------
CREATE TABLE IF NOT EXISTS migration.progress (
  plan_id       bigint PRIMARY KEY REFERENCES migration.plan(id),
  status        text NOT NULL DEFAULT 'pending',
                -- pending|copying|done|failed|skipped
  rows_copied   bigint,
  started_at    timestamptz,
  finished_at   timestamptz,
  error         text,
  detail        text
);

-- migration.blockers: items gating the alpha.* drop ----------------------
CREATE TABLE IF NOT EXISTS migration.blockers (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code         text NOT NULL UNIQUE,
  severity     text NOT NULL,                       -- CRITICAL/HIGH/MED/LOW/INFO
  description  text NOT NULL,
  status       text NOT NULL DEFAULT 'open',        -- open|resolved|waived
  resolution   text,
  resolved_at  timestamptz
);

-- views ------------------------------------------------------------------
CREATE OR REPLACE VIEW migration.v_plan_summary AS
  SELECT source_db, target_db, target_schema, classification, count(*)
  FROM migration.plan
  GROUP BY 1,2,3,4;

CREATE OR REPLACE VIEW migration.v_copy_queue AS
  SELECT id, source_schema, source_table, target_db, target_schema,
         target_table, classification, domain, batch_order
  FROM migration.plan
  WHERE source_db <> target_db
    AND target_table IS NOT NULL
    AND classification NOT IN ('DROP','DROP_SUPERSEDED_BY_CRIMS_ORM')
  ORDER BY batch_order, domain, source_table;

CREATE OR REPLACE VIEW migration.v_blockers_open AS
  SELECT * FROM migration.blockers
  WHERE status = 'open'
    AND severity IN ('CRITICAL','HIGH','MED');

COMMENT ON VIEW migration.v_blockers_open IS
  'Gate for alpha.* drop: an open blocker here defers drop_alpha_until_open_zero.';

-- (skipping CHECK because classification == DROP rows legitimately lack target)

-- plan rows --------------------------------------------------------------
ON CONFLICT (source_db, source_schema, source_table) DO NOTHING;

-- blockers --------------------------------------------------------------

  Sequence (must run in this exact order to prevent change-stream gaps):
    1. copy_plan.sh completes for ALL movers across all 6 domains (Product, Party, Rating, etc.).
    2. App re-pointed to crims in READ-ONLY mode (writers still go to alpha).
    3. Apply crims publications for the migration-source schemas:
         CREATE PUBLICATION crims_cdc_publication FOR TABLE mdm.*, edm.*, oms.*, cash_flow.*;
       (Use crims-side schema names; include only the move-DATA tables per migration.plan.)
    4. Stop the Debezium connector on alpha:
         curl -X DELETE http://localhost:8083/connectors/orm-oms-connector
       (or whichever name was registered; see docker-compose.remote.yml re alpha wiring.)
    5. Start the Debezium connector on crims:
         curl -X POST http://localhost:8083/connectors -d ''{... publication.name=crims_cdc_publication, database.dbname=crims, ...}''
       (After verifying the connector task state on crims reads RUNNING.)
    6. App write phase enabled (dual-write window: writers now mirror to crims).
    7. After dual-write + reconciliation window (24-72h), stop alpha writes and disable the alpha publication.
  This sequence has no idle window where writes happen without CDC.

  Side note (from AGENTS.md): the alpha connector used slot name ''orm_oms_slot'' with publication ''orm_cdc_publication''. Its mTLS certs were placed via the .pk8 workaround at /tmp/orm_client_der.pk8. The crims-side connector needs the same workaround applied to its cert mount.'),
('DROP_GATE', 'INFO', 'open', 'Drop of alpha.{mdm, edm, oms-superseded} schemas gated on migration.v_blockers_open gating_open count = 0. Open for HIGH/MED blockers: see blockers table.')
ON CONFLICT (code) DO NOTHING;

-- QA summary -- counts by classification+target
SELECT classification, target_db || COALESCE('.' || target_schema, '') AS target, count(*) AS rows
FROM migration.plan GROUP BY 1,2 ORDER BY 1,2;

SELECT count(*) FILTER (WHERE status='open' AND severity IN ('CRITICAL','HIGH','MED')) AS gating_open
FROM migration.blockers;
